    /**
     * Performs an INSERT on the database, given a MarcVariableDoc or Criteria object.
     *
     * @param      mixed $values Criteria or MarcVariableDoc object containing data that is used to create the INSERT statement.
     * @param      PropelPDO $con the PropelPDO connection to use
     * @return mixed           The new primary key.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doInsert($values, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(MarcVariableDocPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
        }

        if ($values instanceof Criteria) {
            $criteria = clone $values; // rename for clarity
        } else {
            $criteria = $values->buildCriteria(); // build Criteria from MarcVariableDoc object
        }

        if ($criteria->containsKey(MarcVariableDocPeer::MARCVARIABLEDOC_ID) && $criteria->keyContainsValue(MarcVariableDocPeer::MARCVARIABLEDOC_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key ('.MarcVariableDocPeer::MARCVARIABLEDOC_ID.')');
        }

        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(MarcVariableDocPeer::MARCVARIABLEDOC_ID);


        // Set the correct dbName
        $criteria->setDbName(MarcVariableDocPeer::DATABASE_NAME);

        try {
            // use transaction because $criteria could contain info
            // for more than one table (I guess, conceivably)
            $con->beginTransaction();
            $pk = BasePeer::doInsert($criteria, $con);
            $con->commit();
        } catch (Exception $e) {
            $con->rollBack();
            throw $e;
        }

        return $pk;
    }

    /**
     * Performs an UPDATE on the database, given a MarcVariableDoc or Criteria object.
     *
     * @param      mixed $values Criteria or MarcVariableDoc object containing data that is used to create the UPDATE statement.
     * @param      PropelPDO $con The connection to use (specify PropelPDO connection object to exert more control over transactions).
     * @return int             The number of affected rows (if supported by underlying database driver).
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doUpdate($values, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(MarcVariableDocPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
        }

        $selectCriteria = new Criteria(MarcVariableDocPeer::DATABASE_NAME);

        if ($values instanceof Criteria) {
            $criteria = clone $values; // rename for clarity

            $comparison = $criteria->getComparison(MarcVariableDocPeer::MARCVARIABLEDOC_ID);
            $value = $criteria->remove(MarcVariableDocPeer::MARCVARIABLEDOC_ID);
            if ($value) {
                $selectCriteria->add(MarcVariableDocPeer::MARCVARIABLEDOC_ID, $value, $comparison);
            } else {
                $selectCriteria->setPrimaryTableName(MarcVariableDocPeer::TABLE_NAME);
            }

        } else { // $values is MarcVariableDoc object
            $criteria = $values->buildCriteria(); // gets full criteria
            $selectCriteria = $values->buildPkeyCriteria(); // gets criteria w/ primary key(s)
        }

        // set the correct dbName
        $criteria->setDbName(MarcVariableDocPeer::DATABASE_NAME);

        return BasePeer::doUpdate($selectCriteria, $criteria, $con);
    }

